import React, { useEffect } from 'react';

const ImageViewer = ({ content, closeModal, setCurrentContent }) => {
  const { text, images, carousel, currentImageIndex } = content;

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'Escape') {
        closeModal();
      } else if (e.key === 'ArrowLeft' && carousel && currentImageIndex > 0) {
        handlePrevSlide();
      } else if (e.key === 'ArrowRight' && carousel && currentImageIndex < images.length - 1) {
        handleNextSlide();
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [closeModal, carousel, currentImageIndex, images]);

  const handleNextSlide = () => {
    if (currentImageIndex < images.length - 1) {
      setCurrentContent({
        ...content,
        currentImageIndex: currentImageIndex + 1
      });
    }
  };

  const handlePrevSlide = () => {
    if (currentImageIndex > 0) {
      setCurrentContent({
        ...content,
        currentImageIndex: currentImageIndex - 1
      });
    }
  };

  return (
    <div id="myModal" className="modal">
      <div className="modal-content">
        {carousel ? (
          <>
            <img 
              id="modalImg" 
              src={images[currentImageIndex]} 
              alt="Modal" 
            />
            {images.length > 1 && (
              <>
                <img 
                  className="prev" 
                  onClick={handlePrevSlide} 
                  src="/media/left.webp" 
                  alt="Previous"
                  style={{ display: currentImageIndex === 0 ? 'none' : 'block' }} 
                />
                <img 
                  className="next" 
                  onClick={handleNextSlide} 
                  src="/media/right.webp" 
                  alt="Next"
                  style={{ display: currentImageIndex === images.length - 1 ? 'none' : 'block' }} 
                />
              </>
            )}
          </>
        ) : (
          <img id="modalImg" src={images[0] || ''} alt="Modal" />
        )}
      </div>
      <div 
        id="caption" 
        dangerouslySetInnerHTML={{ __html: text }}
      ></div>
      <span className="close" onClick={closeModal}>&times;</span>
    </div>
  );
};

export default ImageViewer;
